  function removeSelection(graph,selected){const next=copy(graph);if(next.nodes.some(n=>n.id===selected)){next.nodes=next.nodes.filter(n=>n.id!==selected);next.edges=next.edges.filter(e=>e.from_node!==selected&&e.to_node!==selected);}else next.edges=next.edges.filter(e=>e.id!==selected);return next;}
  function fitViewport(nodes,width,height){if(!nodes.length)return{x:35,y:55,scale:1};const minX=Math.min(...nodes.map(n=>Number(n.x)||0)),minY=Math.min(...nodes.map(n=>Number(n.y)||0)),maxX=Math.max(...nodes.map(n=>(Number(n.x)||0)+176)),maxY=Math.max(...nodes.map(n=>(Number(n.y)||0)+(n.height||190)));const scale=Math.min(1.15,Math.max(.12,Math.min((width-70)/(maxX-minX),(height-95)/(maxY-minY))));return{x:(width-(maxX-minX)*scale)/2-minX*scale,y:(height-(maxY-minY)*scale)/2-minY*scale,scale};}
