      this.el.setAttribute('translate','no');this.statusTimer=root.setInterval?.(()=>{if((this.mode==='groups'||this.dialog?.kind==='apply')&&!this.el.ownerDocument.hidden&&!this.el.closest('[hidden]'))this.refreshMetadata();},3000);this.bind();this.render();this.load();
