      const selected=graph.nodes.find(n=>n.id===this.selected);if(!selected&&!graph.edges.some(e=>e.id===this.selected))this.selected=graph.nodes[0]?.id||null;
      this.el.innerHTML=`<div class="wc-shell" aria-label="${esc(this.t('Workflow editor'))}"><header class="wc-head"><div class="wc-heading"><h2>${esc(title)}</h2><p class="wc-subtitle">${esc(this.t(editing?'Draft changes do not alter camera groups until Apply.':'Read-only applied workflow. Edit the shared draft to change blocks.'))}</p></div><div class="wc-actions"><span class="wc-counter ${this.dirty()?'wc-dirty':''}">${esc(this.t(editing?(this.dirty()?'Unsaved changes':'Draft saved'):'Applied snapshot'))}</span>${editing?this.button('save','Save draft','',!workflow||!this.dirty()||this.busy?'disabled':''):''}${this.button('test','Test','',!graph.nodes.length||this.busy?'disabled':'')}${editing?this.button('apply','Apply to groups…','wc-primary',!workflow||this.busy?'disabled':''):this.button('live-results','Live results','wc-primary',!group?'disabled':'')}</div></header>
      <div class="wc-context"><div class="wc-tabs" aria-label="${esc(this.t('Scope'))}">${this.button('mode-edit','Workflow editor','',`aria-pressed="${editing}"`)}${this.button('mode-groups','Camera groups','',`aria-pressed="${!editing}"`)}</div>${editing?`<label class="wc-workflow-picker"><span class="wc-context-label">${esc(this.t('Workflow'))}</span><select data-wc-context="workflow" aria-label="${esc(this.t('Workflow'))}">${this.workflows.length?this.workflows.map(w=>`<option value="${esc(w.id)}" ${w.id===this.workflowId?'selected':''}>${esc(this.drafts.get(w.id)?.name||w.name)}${this.dirty(w.id)?' *':''}</option>`).join(''):`<option value="">${esc(this.t('No workflow'))}</option>`}</select></label>`:`<label><span class="wc-context-label">${esc(this.t('Group'))}</span><select data-wc-context="group" aria-label="${esc(this.t('Group'))}">${this.groups.length?this.groups.map(g=>`<option value="${esc(g.id)}" ${g.id===this.groupId?'selected':''}>${esc(g.name)}</option>`).join(''):`<option value="">${esc(this.t('No group'))}</option>`}</select></label><label><span class="wc-context-label">${esc(this.t('Scope'))}</span><select data-wc-context="scope" aria-label="${esc(this.t('Scope'))}"><option value="all">${esc(this.t('All cameras'))}</option>${(group?.camera_ids||[]).map(id=>`<option value="${esc(id)}" ${id===this.scope?'selected':''}>${esc(this.cameraName(id))}</option>`).join('')}</select></label>`}<div class="wc-actions">${editing?(workflow?this.button('copy','Make a copy','',this.busy?'disabled':''):this.button('new-workflow','New workflow','wc-primary',this.busy?'disabled':'')):this.button('edit-applied','Edit workflow','',!group?.workflow_id?'disabled':'')}${this.button('manage','Manage','',this.busy?'disabled':'')}</div></div>
      <div class="wc-tools">${editing?this.button('library','Blocks','',`aria-pressed="${this.library}"`):this.button('live','Video & analysis')}${this.button('inspector','Settings','',`aria-pressed="${this.inspector}"`)}<span class="wc-spacer"></span>${editing?this.button('undo','Undo','',this.busy||!this.history().length?'disabled':'')+this.button('delete','Delete','wc-danger',this.busy||!this.selected?'disabled':'')+this.button('arrange','Arrange','',this.busy||!graph.nodes.length?'disabled':''):''}<span class="wc-counter">${graph.nodes.length} ${esc(this.t('blocks'))} · ${graph.edges.length} ${esc(this.t('connections'))}</span></div>
      <div class="wc-editor" data-library="${editing&&this.library?'open':'closed'}" data-inspector="${this.inspector?'open':'closed'}"><aside class="wc-library" aria-label="${esc(this.t('Blocks'))}" ${!editing||!this.library?'hidden':''}>${this.renderLibrary()}</aside><div class="wc-board" tabindex="0" aria-label="${esc(this.t('Workflow canvas'))}"><div class="wc-world"><svg class="wc-edges" aria-label="${esc(this.t('Connections'))}"></svg><div class="wc-nodes">${graph.nodes.map(n=>this.renderNode(n)).join('')}</div></div><div class="wc-canvas-note">${esc(this.t(editing?'Draft only':'Applied snapshot'))}${!editing&&group?.workflow_id?' · '+esc(this.workflows.find(w=>w.id===group.workflow_id)?.name||group.workflow_id):''}</div>${!graph.nodes.length?`<div class="wc-empty"><strong>${esc(this.t(editing?(workflow?'Add blocks to begin.':'Create a workflow to begin.'):'No saved workflow'))}</strong><span>${esc(this.t(editing?'Connect an output to a compatible input.':'Choose a workflow in the editor and Apply it to this group.'))}</span>${editing&&!workflow?this.button('new-workflow','New workflow','wc-primary'):!editing&&!group?this.button('new-group','Add group','wc-primary'):''}</div>`:''}<div class="wc-viewport">${this.button('zoom-out','−','',`aria-label="${esc(this.t('Zoom out'))}"`)}<span class="wc-zoom">100%</span>${this.button('zoom-in','+','',`aria-label="${esc(this.t('Zoom in'))}"`)}${this.button('fit','Fit')}</div></div><aside class="wc-inspector" aria-label="${esc(this.t('Settings'))}" ${!this.inspector?'hidden':''}>${this.renderInspector()}</aside></div><section class="wc-live wc-test" ${!this.liveOpen||editing?'hidden':''}>${this.renderLive()}</section><section class="wc-test-results wc-test" ${!this.testOpen?'hidden':''}>${this.renderTest()}</section><div class="wc-feedback" role="status" aria-live="polite"></div><div class="wc-modal" ${!this.dialog?'hidden':''}>${this.renderDialog()}</div></div>`;
